primaryQuery:
run: order_items -> {
  group_by: user_id
  aggregate: first_order is min(created_at)
} -> {
  where: year(first_order) = 2022
  aggregate: new_customers is count()
}

verifyQuery:
run: order_items -> {
  group_by: user_id
  aggregate:
    prior_lines is count() { where: created_at < @2022-01-01 }
    lines_2022 is count() { where: created_at >= @2022-01-01 and created_at < @2023-01-01 }
} -> {
  where: lines_2022 > 0 and prior_lines = 0
  aggregate: new_customers is count()
}
